// src/lib/deploy/site-url.ts
async function writeSiteUrls(token, fullName2, branch, urls) {
  const files = [];
  if (urls.previewUrl) {
    try {
      const file = await getFile2(token, fullName2, ".wuppycms/sites.jsonc", branch);
      let next = file.content;
      if (/"url"\s*:/.test(next)) {
        next = next.replace(/"url"\s*:\s*"[^"]*"/, `"url": ${JSON.stringify(urls.previewUrl)}`);
      } else if (/"name"\s*:/.test(next)) {
        next = next.replace(
          /("name"\s*:\s*"[^"]*",)/,
          `$1
			"url": ${JSON.stringify(urls.previewUrl)},`
        );
      }
      if (next !== file.content) files.push({ path: ".wuppycms/sites.jsonc", content: next });
    } catch (error3) {
      if (!(error3 instanceof BackendError && error3.status === 404)) throw error3;
    }
  }
  if (urls.siteUrl) {
    try {
      const file = await getFile2(token, fullName2, "astro.config.mjs", branch);
      const siteLine = `site: ${JSON.stringify(urls.siteUrl)}`;
      let next = file.content;
      if (/site:\s*["'][^"']*["']/.test(next)) {
        next = next.replace(/site:\s*["'][^"']*["']/, siteLine);
      } else {
        next = next.replace(
          /export default defineConfig\(\{/,
          `export default defineConfig({
	${siteLine},`
        );
      }
      if (next !== file.content) files.push({ path: "astro.config.mjs", content: next });
    } catch (error3) {
      if (!(error3 instanceof BackendError && error3.status === 404)) throw error3;
    }
  }
  if (!files.length) return 0;
  await commitFiles2(
    token,
    fullName2,
    branch,
    files,
    "chore: site adresleri g\xFCncellendi (via WuppyCMS)"
  );
  return files.length;
}

