deploy.get("/status", async (c) => {
  const user = await requireUser(c);
  if (!user) return c.json({ error: "unauthenticated" }, 401);
  const db = platform(c).db;
  if (!db) return c.json({ jobs: [] });
  const repo = c.req.query("full_name");
  const siteUrl2 = c.req.query("url");
  const rows = await db.prepare(
    repo ? `SELECT id, repo_full_name, status, url, preview_url, error, updated_at
				   FROM deploy_jobs WHERE repo_full_name = ? ORDER BY created_at DESC LIMIT 1` : siteUrl2 ? `SELECT id, repo_full_name, status, url, preview_url, error, updated_at
					   FROM deploy_jobs WHERE url = ? ORDER BY created_at DESC LIMIT 1` : `SELECT id, repo_full_name, status, url, preview_url, error, updated_at
					   FROM deploy_jobs ORDER BY created_at DESC LIMIT 20`
  ).bind(...repo ? [repo] : siteUrl2 ? [siteUrl2] : []).all();
  const staleMs = 10 * 6e4;
  const jobs = (rows.results ?? []).map((job) => {
    const row = job;
    if (row.status !== "queued" || !row.updated_at) return job;
    const age = Date.now() - Date.parse(row.updated_at);
    if (!Number.isFinite(age) || age <= staleMs) return job;
    return {
      ...job,
      status: "failed",
      error: "Yay\u0131n kuyru\u011Fu yeniden ba\u015Flad\u0131; yeniden yay\u0131nlay\u0131n."
    };
  });
  return c.json({ jobs });
});

