var previewControl = new Hono3();
var openSchema = external_exports.object({
  full_name: external_exports.string().trim().min(3).max(200),
  branch: external_exports.string().trim().max(200).optional()
});
function managerBase(env2) {
  return env2.PREVIEW_MANAGER_URL || "http://127.0.0.1:8791";
}
function managerHeaders(env2) {
  return {
    "content-type": "application/json",
    ...env2.PREVIEW_SECRET ? { "x-preview-secret": env2.PREVIEW_SECRET } : {}
  };
}
previewControl.post("/open", body(openSchema), async (c) => {
  const user = await requireUser(c);
  if (!user) return c.json({ error: "unauthenticated" }, 401);
  const payload = c.req.valid("json");
  const token = await resolveGitToken(c, payload.full_name);
  if (!token) return c.json({ ok: false, error: "git_not_connected" }, 400);
  let branch = payload.branch;
  if (!branch) {
    try {
      branch = (await getRepo2(token, payload.full_name)).defaultBranch || "main";
    } catch {
      branch = "main";
    }
  }
  const slug2 = siteSlug(payload.full_name);
  try {
    const res = await fetch(`${managerBase(c.env)}/open`, {
      method: "POST",
      headers: managerHeaders(c.env),
      body: JSON.stringify({ slug: slug2, repo: payload.full_name, branch, token }),
      signal: AbortSignal.timeout(14e4)
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) return c.json({ ok: false, slug: slug2, error: data.error ?? "preview_failed" }, 502);
    return c.json({ ok: true, slug: slug2, port: data.port ?? null, ready: data.ready ?? false });
  } catch (error3) {
    return c.json(
      {
        ok: false,
        slug: slug2,
        error: error3 instanceof Error ? error3.message : "preview_unreachable"
      },
      502
    );
  }
});
previewControl.post("/refresh", body(openSchema), async (c) => {
  const user = await requireUser(c);
  if (!user) return c.json({ error: "unauthenticated" }, 401);
  const payload = c.req.valid("json");
  const token = await resolveGitToken(c, payload.full_name);
  if (!token) return c.json({ ok: false, error: "git_not_connected" }, 400);
  const slug2 = siteSlug(payload.full_name);
  try {
    const res = await fetch(`${managerBase(c.env)}/refresh`, {
      method: "POST",
      headers: managerHeaders(c.env),
      body: JSON.stringify({ slug: slug2, token, branch: payload.branch }),
      signal: AbortSignal.timeout(6e4)
    });
    const data = await res.json().catch(() => ({}));
    return c.json({ ok: res.ok && data.ok !== false, slug: slug2, error: data.error }, res.ok ? 200 : 502);
  } catch (error3) {
    return c.json(
      {
        ok: false,
        slug: slug2,
        error: error3 instanceof Error ? error3.message : "preview_unreachable"
      },
      502
    );
  }
});
previewControl.get("/status", async (c) => {
  const user = await requireUser(c);
  if (!user) return c.json({ error: "unauthenticated" }, 401);
  const slug2 = c.req.query("slug") ?? "";
  if (!/^[a-z0-9][a-z0-9-]{2,80}$/.test(slug2)) {
    return c.json({ ok: false, error: "invalid_slug" }, 400);
  }
  try {
    const res = await fetch(`${managerBase(c.env)}/status?slug=${encodeURIComponent(slug2)}`, {
      headers: c.env.PREVIEW_SECRET ? { "x-preview-secret": c.env.PREVIEW_SECRET } : {},
      signal: AbortSignal.timeout(2500)
    });
    const data = await res.json().catch(() => ({}));
    return c.json({ ok: res.ok, slug: slug2, ...data });
  } catch {
    return c.json({ ok: false, slug: slug2, running: false, ready: false });
  }
});

